<?php if($reservations): ?><div class="table-wrap"><table><thead><tr><th>Car</th><th>Rental dates</th><th>Days</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($reservations as $r): ?><tr><td><div class="table-car"><span class="table-car-icon">🚘</span><span><b><?= e($r['car_name']) ?></b><small><?= e($r['model']) ?></small></span></div></td><td><?= e($r['pickup_date']) ?><small class="table-sub">to <?= e($r['return_date']) ?></small></td><td><?= (int)$r['days'] ?></td><td><?= money($r['total_amount']) ?></td><td><span class="status status-<?= e($r['status']) ?>"><?= e(ucfirst($r['status'])) ?></span></td><td><?php if($r['status']==='pending'): ?><form method="post" action="<?= e(url('cancel-reservation.php')) ?>" data-confirm="Cancel this reservation request?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="table-action">Cancel</button></form><?php else: ?><span class="muted">—</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><div class="empty-icon">▣</div><h3>No reservations yet</h3><p>Your booking requests will appear here.</p><a class="btn btn-primary" href="<?= e(url('cars.php')) ?>">Explore cars</a></div><?php endif; ?>
